test('slugify lowercases and joins words with dashes', () => {
  assert.equal(slugify('Hello, World!'), 'hello-world');
});

test('slugify removes diacritics', () => {
  assert.equal(slugify('Crème Brûlée'), 'creme-brulee');
});

test('slugify collapses runs and trims dashes', () => {
  assert.equal(slugify('  Ship it -- now  '), 'ship-it-now');
});

test('slugify returns empty string without letters or digits', () => {
  assert.equal(slugify(''), '');
  assert.equal(slugify('!!! ---'), '');
});

test('slugify keeps digits', () => {
  assert.equal(slugify('Top 10 of 2024'), 'top-10-of-2024');
});
EOF
npm test 2>&1 | tail -25

